function fileData(input,fallback=''){
  const file=input?.files?.[0];
  if(!file)return Promise.resolve(fallback||'');
  return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=()=>reject(new Error('Unable to read logo file.'));reader.readAsDataURL(file)})
}
