async function savePersonalActivity(e){e.preventDefault();const p=person(currentPersonnelId);if(!p)return;const id=$('paId').value,payload={workspace_id:workspaceId,personnel_id:p.id,client_id:$('paClient').value||null,measurement_id:null,unit_type:p.unit_type,record_type:'consistency',record_date:$('paDate').value,severity:1,distress_level:0,description:$('paDescription').value.trim(),action_taken:$('paAction').value||null};if(!id)payload.created_by=session.user.id;loading(true);try{let r=id?await sb.from('activity_records_v2').update(payload).eq('id',id):await sb.from('activity_records_v2').insert(payload);if(r.error)throw r.error;closeModal();await reload();toast(id?'Work log updated.':'Work logged.')}catch(err){toast(err.message||'Unable to log work.',true)}finally{loading(false)}}

activityHTML=arr=>arr.length?arr.map(a=>{const pts=activityPoints(a),scored=!!(a.measurement_id&&measure(a.measurement_id)),canEdit=isExec()||(isPersonal()&&a.personnel_id===currentPersonnelId&&!scored);return `<div class="activity-item"><div class="activity-icon ${a.record_type}">${a.task_id?'✓':a.record_type==='error'?'!':a.record_type==='achievement'?'★':'✓'}</div><div><strong>${esc(a.task_id&&!scored?'Task completed':measure(a.measurement_id)?.name||(scored?a.record_type:'Work log'))}</strong><span>${isPersonal()?'My log':esc(person(a.personnel_id)?.name||'Personnel')} · ${esc(client(a.client_id)?.name||'Internal')}</span>${a.description?`<span>${esc(a.description)}</span>`:''}${a.action_taken?`<span>Follow-up: ${esc(a.action_taken)}</span>`:''}<span class="activity-points ${!scored?'neutral':''}">${scored?(pts>0?'+':'')+pts:'Awaiting review'}</span></div><div class="activity-meta"><time>${activityTime(a)||a.record_date}</time>${canEdit?`<div class="activity-actions"><button type="button" onclick="event.stopPropagation();activityModal({activityId:'${a.id}'})">Edit</button><button type="button" class="delete-activity" onclick="event.stopPropagation();deleteActivity('${a.id}')">Delete</button></div>`:''}</div></div>`}).join(''):'<div class="panel muted">No activity found.</div>';

