function taskStatusChip(t){return `<span class="task-status status-${t.status}">${taskStatusLabels[t.status]||t.status}</span>`}
function taskBoardCard(t){
  const due=t.due_at?new Date(t.due_at).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'No deadline';
  const canSelf=isPersonal()&&taskForPerson(t,currentPersonnelId),canCheck=(isExec()||canSelf)&&t.status!=='completed';
  return `<article class="trello-task" onclick="openTask('${t.id}')"><div class="trello-task-top"><button class="task-check ${t.status==='completed'?'checked':''}" title="${t.status==='completed'?'Completed':'Mark completed'}" onclick="event.stopPropagation();${canCheck?`setTaskStatus('${t.id}','completed')`:''}">${t.status==='completed'?'✓':''}</button><div class="trello-task-copy"><small>${esc(taskClient(t.client_id)?.name||'Internal')}</small><strong>${esc(t.title)}</strong></div>${taskStatusChip(t)}</div>${t.details?`<p>${esc(t.details)}</p>`:''}<div class="trello-task-meta"><span>Due ${due}</span><span>${[t.designer_id,t.manager_id,t.supervisor_id].filter(Boolean).map(id=>esc(person(id)?.name||'')).filter(Boolean).join(' · ')||'Unassigned'}</span></div></article>`;
}
function renderTasks(){
  if(!$('taskList'))return;const q=($('taskSearch')?.value||'').trim().toLowerCase(),status=$('taskStatus')?.value||'active',pid=$('taskPerson')?.value||'all';
  if(isExec()&&$('taskPerson')){const old=$('taskPerson').value||'all';$('taskPerson').innerHTML='<option value="all">All personnel</option>'+people.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');$('taskPerson').value=[...$('taskPerson').options].some(o=>o.value===old)?old:'all'}
  let arr=[...tasks];if(status==='active')arr=arr.filter(t=>taskActiveStates.has(t.status));else if(status!=='all')arr=arr.filter(t=>t.status===status);if(pid!=='all')arr=arr.filter(t=>taskForPerson(t,pid));if(q)arr=arr.filter(t=>[t.title,t.details,client(t.client_id)?.name].some(v=>String(v||'').toLowerCase().includes(q)));
  const active=tasks.filter(t=>taskActiveStates.has(t.status)).length,completed=tasks.filter(t=>t.status==='completed').length,delayed=tasks.filter(t=>t.status==='delayed').length,today=localDateKey(new Date()),dueToday=tasks.filter(t=>taskActiveStates.has(t.status)&&t.due_at?.slice(0,10)===today).length;
  $('taskSummary').innerHTML=[['ACTIVE',active],['DUE TODAY',dueToday],['DELAYED',delayed],['COMPLETED',completed]].map(([a,b])=>`<article><span>${a}</span><strong>${b}</strong></article>`).join('');
  const columns=[['TO DO',['assigned']],['IN PROGRESS',['in_progress']],['WAITING',['delayed','postponed']],['CLOSED',['completed','cancelled','rejected']]];
  $('taskList').className='task-board';
  $('taskList').innerHTML=columns.map(([label,states])=>{const rows=arr.filter(t=>states.includes(t.status));return `<section class="task-board-column"><header><strong>${label}</strong><span>${rows.length}</span></header><div class="task-board-cards">${rows.map(taskBoardCard).join('')||'<div class="task-board-empty">No tasks</div>'}</div></section>`}).join('');
}
window.taskModal=(id='')=>{if(!isExec())return toast('Only management can assign or edit tasks.',true);const t=tasks.find(x=>x.id===id)||{},personOpts=(selected)=>'<option value="">Unassigned</option>'+people.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)} · ${(p.clearance_level||'p').toUpperCase()}</option>`).join('');openModal(id?'Edit Task':'New Task',`<form id="taskForm"><input id="tId" type="hidden" value="${id}"><div class="form-grid"><div><label>Client</label><select id="tClient"><option value="">Internal / no client</option>${taskClientDirectory.map(c=>`<option value="${c.id}" ${c.id===t.client_id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div><label>Deadline</label><input id="tDue" type="datetime-local" value="${dateTimeLocalValue(t.due_at)}"></div><div class="full"><label>Task</label><input id="tTitle" required value="${esc(t.title||'')}" placeholder="Maintenance carousel poster"></div><div class="full"><label>Brief / details</label><textarea id="tDetails">${esc(t.details||'')}</textarea></div><div><label>Designer</label><select id="tDesigner">${personOpts(t.designer_id)}</select></div><div><label>Manager</label><select id="tManager">${personOpts(t.manager_id)}</select></div><div><label>Supervisor</label><select id="tSupervisor">${personOpts(t.supervisor_id)}</select></div><div><label>Current state</label><div class="readonly-note">${taskStatusLabels[t.status||'assigned']}</div></div></div><div class="modal-actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save task</button></div></form>`,'TASK');$('taskForm').onsubmit=saveTask};
async function saveTask(e){e.preventDefault();const id=$('tId').value,payload={workspace_id:workspaceId,client_id:$('tClient').value||null,title:$('tTitle').value.trim(),details:$('tDetails').value||null,designer_id:$('tDesigner').value||null,manager_id:$('tManager').value||null,supervisor_id:$('tSupervisor').value||null,due_at:$('tDue').value?new Date($('tDue').value).toISOString():null,updated_at:new Date().toISOString()};if(!id){payload.created_by=session.user.id;payload.status='assigned'}loading(true);try{let r=id?await sb.from('tasks').update(payload).eq('id',id).select().single():await sb.from('tasks').insert(payload).select().single();if(r.error)throw r.error;if(!id){let ev=await sb.from('task_events').insert({workspace_id:workspaceId,task_id:r.data.id,event_type:'assigned',created_by:session.user.id});if(ev.error)throw ev.error}closeModal();await reload();toast(id?'Task updated.':'Task assigned.')}catch(err){toast(err.message||'Unable to save task.',true)}finally{loading(false)}}
window.openTask=id=>{const t=tasks.find(x=>x.id===id);if(!t)return;const due=t.due_at?new Date(t.due_at).toLocaleString():'No deadline',assignedAt=new Date(t.assigned_at).toLocaleString(),completed=t.completed_at?new Date(t.completed_at).toLocaleString():'—',events=taskEvents.filter(e=>e.task_id===id);const assignedSelf=isPersonal()&&taskForPerson(t,currentPersonnelId),canAct=isExec()||assignedSelf;$('drawerBody').innerHTML=`<div class="drawer-profile"><div class="overline">TASK</div><h1>${esc(t.title)}</h1><p class="muted">${esc(taskClient(t.client_id)?.name||'Internal / no client')}</p><div class="task-drawer-status">${taskStatusChip(t)}</div><p>${esc(t.details||'No additional brief.')}</p><div class="summary-row"><div><small>ASSIGNED</small><strong>${assignedAt}</strong></div><div><small>DEADLINE</small><strong>${due}</strong></div><div><small>COMPLETED</small><strong>${completed}</strong></div><div><small>STATE</small><strong>${taskStatusLabels[t.status]}</strong></div></div><div class="task-owner-cards"><div><small>DESIGNER</small><b>${esc(person(t.designer_id)?.name||'—')}</b></div><div><small>MANAGER</small><b>${esc(person(t.manager_id)?.name||'—')}</b></div><div><small>SUPERVISOR</small><b>${esc(person(t.supervisor_id)?.name||'—')}</b></div></div>${t.status_reason?`<section class="lifecycle-panel"><strong>${esc(taskStatusLabels[t.status])}</strong><p>${esc(t.status_reason)}</p></section>`:''}<div class="person-actions">${isExec()?`<button onclick="taskModal('${id}')">EDIT TASK</button>`:''}${canAct&&t.status!=='completed'?`<button class="btn primary" onclick="setTaskStatus('${id}','completed')">✓ COMPLETE</button>`:''}${assignedSelf&&t.status==='assigned'?`<button onclick="setTaskStatus('${id}','in_progress')">START WORK</button>`:''}${isExec()?`<button onclick="setTaskStatus('${id}','in_progress')">IN PROGRESS</button><button onclick="setTaskStatus('${id}','delayed')">DELAYED</button><button onclick="setTaskStatus('${id}','postponed')">POSTPONED</button>`:''}${canAct?`<button class="btn danger" onclick="setTaskStatus('${id}','cancelled')">CANCEL</button><button class="btn danger" onclick="setTaskStatus('${id}','rejected')">REJECT</button>`:''}</div><h2>STATE HISTORY</h2><div class="event-list">${events.length?events.map(e=>`<div><b>${esc(taskStatusLabels[e.event_type]||e.event_type)}</b><span>${new Date(e.created_at).toLocaleString()}${e.reason?' · '+esc(e.reason):''}</span></div>`).join(''):'<div class="muted">No state history yet.</div>'}</div></div>`;$('drawer').classList.remove('hidden')};
window.setTaskStatus=async(id,status)=>{let reason=null;if(['cancelled','rejected','delayed','postponed'].includes(status)){reason=prompt(`Reason for ${taskStatusLabels[status]}:`);if(reason===null)return;if(!reason.trim())return toast('A reason is required.',true)}loading(true);try{const r=await sb.rpc('shadowops_set_task_status',{task_uuid:id,new_status:status,reason_text:reason});if(r.error)throw r.error;$('drawer').classList.add('hidden');await reload();toast(status==='completed'?'Task completed and added to Activity.':'Task state updated.')}catch(err){toast(err.message||'Unable to update task.',true)}finally{loading(false)}};
function renderOverviewTaskLoad(){if(!$('overviewTaskLoad')||!isExec())return;const today=localDateKey(new Date()),rows=people.map(p=>{const active=activeTasksForPerson(p.id),due=active.filter(t=>t.due_at?.slice(0,10)===today).length,delayed=active.filter(t=>t.status==='delayed').length;return {p,active:active.length,due,delayed}}).sort((a,b)=>b.active-a.active||b.due-a.due);$('overviewTaskLoad').innerHTML=rows.length?rows.map(x=>`<button onclick="setPage('tasks');setTimeout(()=>{if($('taskPerson')){$('taskPerson').value='${x.p.id}';renderTasks()}},0)">${avatarMarkup(x.p,'task-avatar')}<span><b>${esc(x.p.name)}</b><small>${x.active} active · ${x.due} due today${x.delayed?' · '+x.delayed+' delayed':''}</small></span><strong>${x.active}</strong></button>`).join(''):'<div class="muted">No personnel.</div>'}

// ---------------------------------------------------------------------------
// Revenue
// ---------------------------------------------------------------------------
function lifecycleStatusAt(c,month){const end=new Date(month+'-01T00:00:00');end.setMonth(end.getMonth()+1);end.setMilliseconds(-1);const ev=lifecycleEvents.filter(e=>e.client_id===c.id&&new Date(e.changed_at)<=end).sort((a,b)=>new Date(b.changed_at)-new Date(a.changed_at))[0];return ev?.status||'active'}
function clientRevenueForMonth(c,month){const explicit=revenueMonths.find(r=>r.client_id===c.id&&String(r.month).slice(0,7)===month);if(explicit)return explicit.billing_status==='billable'?Number(explicit.override_amount_mnt??c.monthly_price_mnt??0):0;const start=new Date(month+'-01T00:00:00'),end=new Date(start);end.setMonth(end.getMonth()+1);end.setMilliseconds(-1);const cs=c.contract_start?new Date(c.contract_start+'T00:00:00'):new Date(c.created_at||0),ce=c.contract_end?new Date(c.contract_end+'T23:59:59'):null;if(cs>end||ce&&ce<start)return 0;const override=revenueMonths.find(r=>r.client_id===c.id&&String(r.month).slice(0,7)===month);if(override){if(override.billing_status!=='billable')return 0;return Number(override.override_amount_mnt??c.monthly_price_mnt??0)}const st=lifecycleStatusAt(c,month);if(['paused','ended','archived'].includes(st))return 0;return Number(c.monthly_price_mnt||0)}
function bonusForMonth(month){return bonusWorks.filter(b=>b.work_date?.slice(0,7)===month).reduce((s,b)=>s+Number(b.amount_mnt||0),0)}
function retainerForMonth(month){return clients.reduce((s,c)=>s+clientRevenueForMonth(c,month),0)}
function revenueForMonth(month,mode='combined'){const r=retainerForMonth(month),b=bonusForMonth(month);return mode==='retainer'?r:mode==='bonus'?b:r+b}
