window.selfAvatarModal=()=>{if(!isPersonal()||!currentPersonnelId)return;const p=person(currentPersonnelId);openModal('Profile Picture',`<form id="selfAvatarForm"><div class="profile-uploader"><div id="selfAvatarPreview" class="profile-preview">${p.avatar_data?`<img src="${p.avatar_data}" alt="">`:initials(p.name)}</div><div><label class="btn" for="selfAvatarFile">Choose photo</label><input id="selfAvatarFile" class="hidden" type="file" accept="image/png,image/jpeg,image/webp"><button type="button" id="selfAvatarRemove" class="btn ghost">Remove</button><small class="muted">PNG, JPG or WebP · maximum 2 MB.</small></div></div><div class="modal-actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save photo</button></div></form>`,'PROFILE');let next=p.avatar_data||null;$('selfAvatarFile').onchange=e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>2_000_000){e.target.value='';return toast('Keep profile images under 2 MB.',true)}const r=new FileReader();r.onload=()=>{next=r.result;$('selfAvatarPreview').innerHTML=`<img src="${r.result}" alt="">`};r.readAsDataURL(f)};$('selfAvatarRemove').onclick=()=>{next=null;$('selfAvatarFile').value='';$('selfAvatarPreview').textContent=initials(p.name)};$('selfAvatarForm').onsubmit=async e=>{e.preventDefault();loading(true);try{const r=await sb.rpc('shadowops_update_own_avatar',{ws:workspaceId,avatar_value:next});if(r.error)throw r.error;closeModal();await reload();toast('Profile picture updated.')}catch(err){toast(err.message,true)}finally{loading(false)}}};

