async function saveTeamAccess(e){e.preventDefault();loading(true);try{const r=await sb.rpc('shadowops_add_member',{ws:workspaceId,member_email:$('accessEmail').value,level:$('accessLevel').value,linked_personnel:$('accessPerson').value||null});if(r.error)throw r.error;closeModal();await renderTeamAccess();toast(r.data==='invite_staged'?'Access staged. They can create/sign in with that email to join this workspace.':'Account added to this ShadowOPS workspace.')}catch(err){toast(err.message||'Unable to add access.',true)}finally{loading(false)}}
window.editTeamMember=userId=>{if(!isOwner())return;const m=(teamAccessData.members||[]).find(x=>x.user_id===userId);if(!m)return;openModal('Edit Access',`<form id="editAccessForm"><input id="editAccessUser" type="hidden" value="${userId}"><div class="form-grid"><div class="full readonly-note">${esc(m.email||'Account')}</div><div><label>Clearance</label><select id="editAccessLevel">${['e','m','p','a'].map(x=>`<option value="${x}" ${m.access_level===x?'selected':''}>${accessLabels[x]}</option>`).join('')}</select></div><div><label>Linked profile</label><select id="editAccessPerson"><option value="">Not linked</option>${people.map(p=>`<option value="${p.id}" ${m.personnel_id===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div></div><div class="modal-actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save access</button></div></form>`,'ACCESS');$('editAccessForm').onsubmit=async e=>{e.preventDefault();loading(true);try{let r=await sb.rpc('shadowops_update_member',{ws:workspaceId,target_user:userId,level:$('editAccessLevel').value,linked_personnel:$('editAccessPerson').value||null});if(r.error)throw r.error;closeModal();await renderTeamAccess();toast('Access updated.')}catch(err){toast(err.message,true)}finally{loading(false)}}};
window.removeTeamMember=async userId=>{if(!isOwner()||!confirm('Remove this account from the ShadowOPS workspace?'))return;let r=await sb.rpc('shadowops_remove_member',{ws:workspaceId,target_user:userId});if(r.error)return toast(r.error.message,true);await renderTeamAccess();toast('Access removed.')};
window.cancelTeamInvite=async inviteId=>{if(!isOwner()||!confirm('Cancel this pending access?'))return;let r=await sb.rpc('shadowops_cancel_invite',{ws:workspaceId,invite_uuid:inviteId});if(r.error)return toast(r.error.message,true);await renderTeamAccess();toast('Pending access cancelled.')};

