window.weeklyMeasurementModal=pid=>{if(!isExec())return toast('Only senior personnel can give performance measurements.',true);const p=person(pid);if(!p)return;const ms=measures.filter(m=>m.unit_type===p.unit_type);openModal('Weekly Performance Measurement',`<form id="weeklyMeasureForm"><div class="form-grid"><div class="full"><label>Personnel</label><div class="readonly-note">${esc(p.preferred_name||p.name)} · ${p.unit_type.toUpperCase()}</div></div><div><label>Date</label><input id="wmDate" type="date" value="${localDateKey(new Date())}"></div><div><label>Measurement</label><select id="wmMeasure" required>${ms.map(m=>`<option value="${m.id}">${esc(m.name)} · ${m.record_type==='error'?'-':'+'}${Math.abs(Number(m.points||1))} pt</option>`).join('')}</select></div><div class="full"><label>Weekly context</label><textarea id="wmNote" placeholder="What happened this week? Compliment, consistency, error, etc."></textarea></div></div><div class="modal-actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Add performance points</button></div></form>`,'PERFORMANCE');$('weeklyMeasureForm').onsubmit=async e=>{e.preventDefault();const m=measure($('wmMeasure').value);loading(true);try{const r=await sb.from('activity_records_v2').insert({workspace_id:workspaceId,personnel_id:pid,client_id:null,measurement_id:m.id,unit_type:p.unit_type,record_type:m.record_type,record_date:$('wmDate').value,severity:1,distress_level:0,description:$('wmNote').value||null,action_taken:null,created_by:session.user.id});if(r.error)throw r.error;closeModal();await reload();toast('Weekly performance measurement added.')}catch(err){toast(err.message,true)}finally{loading(false)}}};

