renderOverviewTaskLoad=()=>{if(!$('overviewTaskLoad')||!isExec())return;const day=localDateKey(new Date()),today=tasks.filter(t=>taskVisibleOnDay(t,day)&&taskActiveStates.has(t.status)),ps=people.filter(p=>p.is_active!==false),rows=ps.map(p=>{const active=today.filter(t=>taskForPerson(t,p.id)),load=active.reduce((s,t)=>s+taskLoadPoints(t),0),high=active.filter(t=>effectiveTaskUrgency(t)===3).length;return {p,active,load,high}}).sort((a,b)=>b.load-a.load),avg=rows.length?rows.reduce((s,x)=>s+x.load,0)/rows.length:0,max=Math.max(1,...rows.map(x=>x.load)),clientRows=taskClientDirectory.map(c=>{const ts=today.filter(t=>t.client_id===c.id);return {c,load:ts.reduce((s,t)=>s+taskLoadPoints(t),0),n:ts.length}}).sort((a,b)=>b.load-a.load),cmax=Math.max(1,...clientRows.map(x=>x.load));$('overviewTaskLoad').innerHTML=`<div class="load-summary"><div><small>TODAY LOAD</small><b>${rows.reduce((s,x)=>s+x.load,0)}</b></div><div><small>AVG / PERSON</small><b>${avg.toFixed(1)}</b></div><div><small>HIGHEST</small><b>${esc(rows[0]?.p?.preferred_name||rows[0]?.p?.name||'—')}</b></div><div><small>CLIENTS WITH NO WORK</small><b>${clientRows.filter(x=>x.n===0).length}</b></div></div><div class="load-bars">${rows.map(x=>`<button onclick="setPage('tasks');setTimeout(()=>{$('taskDate').value='${day}';$('taskPerson').value='${x.p.id}';taskBoardGroup='person';renderTasks()},0)"><span class="load-name">${avatarMarkup(x.p,'task-avatar')}<b>${esc(x.p.preferred_name||x.p.name)}</b></span><span class="load-track"><i style="width:${x.load/max*100}%"></i></span><strong>${x.load}</strong><small>${x.active.length} tasks${x.high?' · '+x.high+' high':''}</small></button>`).join('')}</div><div class="load-client-grid">${clientRows.slice(0,12).map(x=>`<button onclick="setPage('tasks');setTimeout(()=>{$('taskDate').value='${day}';$('taskClientFilter').value='${x.c.id}';taskBoardGroup='client';renderTasks()},0)"><b>${esc(x.c.name)}</b><span class="load-track"><i style="width:${x.load/cmax*100}%"></i></span><strong>${x.load}</strong></button>`).join('')}</div>`};

