// v1.11: independent management and financial permissions.
function canFinance(){return ['owner','e'].includes(currentAccess);}
function clientOutputs(c){return `${Number(c.poster_count)||0} Posts · ${Number(c.photo_count)||0} Photos · ${Number(c.reel_count)||0} Reels · ${Number(c.story_count)||0} Stories`;}
