const clientModalV110=window.clientModal;window.clientModal=(id='')=>{clientModalV110(id);const c=client(id)||{},grid=$('clientForm')?.querySelector('.form-grid');if(grid&&!$('cPhotos'))grid.insertAdjacentHTML('beforeend',`<div><label>Monthly photos</label><input id="cPhotos" type="number" min="0" step="1" value="${Number(c.photo_count)||0}"></div><div><label>Monthly stories</label><input id="cStories" type="number" min="0" step="1" value="${Number(c.story_count)||0}"></div>`);if(!canFinance())for(const id of ['cMonthlyPrice','cNotes'])$(id)?.closest('div')?.classList.add('hidden');};
function taskVisibleOnDay(t,day){const planned=taskPlanDate(t);if(planned===day)return true;if(planned>day)return false;if(!processDone(t)&&!isException(t))return true;return !!t.completed_at&&ubDate(t.completed_at)===day;}
function taskDelayDays(t,day=$('taskDate')?.value||localDateKey(new Date())){if(processDone(t)||isException(t))return 0;return Math.max(0,Math.floor((Date.parse(day)-Date.parse(taskPlanDate(t)))/86400000));}
function effectiveTaskUrgency(t,day){const days=taskDelayDays(t,day);return Math.max(Number(t.priority)||2,days>=4?3:days>0?2:1);}
taskStandupRow=t=>{const delay=taskDelayDays(t),level=effectiveTaskUrgency(t);return `<article class="standup-task v17-task urgency-edge-${level}" onclick="openTask('${t.id}')"><div class="v17-task-content"><small>${esc(taskClient(t.client_id)?.name||'Internal')} · ${esc(t.work_type||'Task')}</small><button class="task-title-button" onclick="event.stopPropagation();openTask('${t.id}')">${esc(t.title)}</button><div class="task-tags">${urgencyBadge({priority:level})}${t.project_id?'<span class="project-tag">PLAYTIME</span>':''}</div><small>Planned ${taskPlanDate(t)} · ${t.due_at?'Due '+new Date(t.due_at).toLocaleString():'No deadline'}</small></div><div class="task-inline-controls" onclick="event.stopPropagation()"><select aria-label="Process for ${esc(t.title)}" onchange="changeProcessInline('${t.id}',this.value)" ${canChangeTask(t)&&!isException(t)?'':'disabled'}>${isException(t)?`<option>${esc(t.status)}</option>`:processSteps.map(([k,n])=>`<option value="${k}" ${processOf(t)===k?'selected':''}>${n}</option>`).join('')}</select>${delay?`<span class="delay-circle delay-${delay>=4?'red':delay>=2?'orange':'yellow'}" title="${delay} days carried over" aria-label="${delay} days carried over">${delay}<small>d</small></span>`:''}</div></article>`;};
